import{_ as e,c as a,a2 as _,o as p}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百三十九章 四个人相继活到一百岁","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/139第一百三十九章 四个人相继活到一百岁.md","filePath":"meditation/巴利文大藏经/139第一百三十九章 四个人相继活到一百岁.md"}'),o={name:"meditation/巴利文大藏经/139第一百三十九章 四个人相继活到一百岁.md"};function r(n,t,i,s,d,c){return p(),a("div",null,t[0]||(t[0]=[_('<h1 id="第一百三十九章-四个人相继活到一百岁" tabindex="-1">第一百三十九章 四个人相继活到一百岁 <a class="header-anchor" href="#第一百三十九章-四个人相继活到一百岁" aria-label="Permalink to &quot;第一百三十九章 四个人相继活到一百岁&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部15相应7经/弟子经(无始相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，众多的出家弟子们来到佛陀的住所，他们顶礼佛陀后，就在一旁坐下，他们对佛陀说：“世尊，到现在为止，已经过去多少劫（劫解释，见第一百三十七章）了呢？”</p><p>佛陀说：“弟子们，已经过去很多劫了，这些已经过去劫的数量不太好估算，如果用像几劫、几百劫、几千劫、几十万劫这样的数量来估算的话，那是无法估算出来的，因为已经过去劫的数量是无数的，是无法估量的。”</p><p>出家弟子们继续说：“世尊，您可以为我们说一个比喻吗？用这个比喻来描述过去劫数量的多少，用这个比喻来说明过去劫的无数、无量。”</p><p>佛陀说：“弟子们，说比喻还是可以的，就比如四个有一百年寿命的出家人，他们相继的出生在世间，也就是说他们四个人分四次相继的出生在世间，第一个人出生在世间活到一百岁后死去，第二个人接着第一个死去的人继续的出生在世间活到一百岁后死去，第三个人接着第二个死去的人继续的出生在世间活到一百岁后死去，第四个人接着第三个死去的人继续出生在世间活到一百岁后死去，弟子们这就是相继的出生到世间又相继的死去，这四个出家人，他们中的第一个人从出生在世间的那一刻起，就开始每天计数十万劫，到第一个人活到一百岁后死去，第二个人相续的出生在世间，他按着第一个死去人的计数继续每天计数十万劫，到第二个人活到一百岁后死去，第三个人相续出生在世间，他按着第二个死去人的计数继续每天计数十万劫，到第三个人活到一百岁死后，第四个人相继的出生在世间，他按着第三个死去人的计数继续每天计数十万劫，直到第四个人活到一百岁后死去，这四个出家人计数劫的总数量，都还无法计算完过去劫的数量，过去劫的数量就有这样的多，过去劫的数量实际上是无限的、是无数的、是无量的、是无法测量的，这是为什么呢？弟子们，因为生死轮回是永无止境的，是无穷无尽的！所以过去的劫也是永无止境、无穷无尽的。这些不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回也是循环不止的，也是无穷无尽的，他们也是无法知道他们自己生死轮回的起点在什么地方的。</p><p>弟子们，你们无数次的生死轮回，无数次的承受痛苦，无数次的经历不幸，无数次的忧愁、悲伤、苦闷、忧虑、绝望。无数次的死后埋入墓地。弟子们，你们要从世间解脱出来，要从生死轮回中解脱出来，就不要再挂念和执着世间一切的事物，就不要再执着和挂念自己一切的行为、言语、念想。这样你们就不会被世间一切的事物束缚捆绑，这样你们就不会被自己的行为、言语、念想束缚捆绑。这样你们就能最终从生死轮回中永远的解脱出来。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
